interactions.sample_code:
let x = y.left;
let beta = x.right;

// 1. Move beta to y's left
setLeft(y, beta);
// 2. Make y the right child of x
setRight(x, y);
// 3. Connect parent to x
setParentLink(x);

interactions.buggy_code:
let x = y.left;

// Swap parent-child roles
setRight(x, y);
setParentLink(x);

// BUG: We forgot to reattach beta! 
// y.left still points to x, creating a closed cycle.

